"""Build a small company-style set without asserting historical interview use."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "src" / "data" / "admin_company_practice_batch_001.json"

# Questions are authored as generic practice tied to a relevant role/company
# context. The associations do not claim that a company asked these questions.
CARDS = [
    ("TCS", "Graduate Engineer Trainee", "Technical Screening", "Computer Networks", "HTTP APIs", "A placement portal receives the same payment callback twice after a timeout. Which API design prevents duplicate charges?", ["Make the callback idempotent with a stable transaction key", "Retry every callback without storing its ID", "Use GET for all payment changes", "Disable server-side transaction checks"], "A", "An idempotency key lets the server recognize retries and return the original result without applying the payment twice.", ["Correct: a stable idempotency key makes retries safe.", "Incorrect: blind retries can apply the payment twice.", "Incorrect: GET should be safe and must not perform payment mutations.", "Incorrect: server-side transaction checks are required to prevent duplicate effects."], "Backend Developer"),
    ("Infosys", "Software Engineer", "Technical Interview", "DBMS and SQL", "Indexing", "A report repeatedly filters a large Orders table by customer_id and sorts by created_at. Which change is the most targeted first step?", ["Add a composite index beginning with customer_id and including created_at", "Add an index to an unrelated display-name column", "Remove the primary key", "Convert the table to an unordered text file"], "A", "A composite index that matches the equality filter followed by the sort can reduce scanned and sorted rows; confirm it with the query plan.", ["Correct: the index aligns with the filter and ordering columns.", "Incorrect: an unrelated index does not support this predicate or sort.", "Incorrect: removing the primary key weakens integrity and does not optimize this query.", "Incorrect: an unordered text file removes database indexing and query capabilities."], "Backend Developer"),
    ("Wipro", "Graduate Engineer Trainee", "Technical Screening", "Operating Systems", "Memory Management", "A long-running service's resident memory rises after each request, while request objects should become unreachable. Which investigation best tests for a memory leak?", ["Capture heap snapshots over time and compare retained object paths", "Increase the log level and assume the leak is fixed", "Restart after every request", "Disable garbage collection permanently"], "A", "Heap snapshots reveal objects retained across request cycles and the references preventing their collection.", ["Correct: retained-object comparisons can expose leaked references.", "Incorrect: logging level alone does not identify object retention.", "Incorrect: restarting masks symptoms and destroys evidence rather than locating the leak.", "Incorrect: disabling garbage collection generally increases memory pressure."], "Software Engineer"),
    ("Accenture", "Backend Developer", "Technical Interview", "Cybersecurity", "OAuth and API Security", "A mobile app calls a backend that must authorize access to a user's records. Where should the authorization decision be enforced?", ["On the backend for each protected operation", "Only in the mobile app's hidden button state", "Only in a client-side URL parameter", "Only in a database name chosen by the user"], "A", "The backend is trusted to authenticate the request and authorize each protected resource operation; client UI checks are not security controls.", ["Correct: enforce access at the trusted server boundary for every operation.", "Incorrect: users can alter client code and invoke endpoints directly.", "Incorrect: URL parameters are user-controlled and cannot establish permission.", "Incorrect: a user-selected database name does not prove identity or access rights."], "Backend Developer"),
    ("Cognizant", "Software Engineer", "Technical Interview", "DBMS and SQL", "Transactions", "An order update must decrement inventory and create an order row together. What property is needed if either write fails?", ["Atomicity", "Denormalization", "Sharding", "Eventual consistency only"], "A", "Atomicity makes the grouped writes commit together or roll back together, preventing a partially applied order.", ["Correct: atomicity provides all-or-nothing transaction behavior.", "Incorrect: denormalization changes data layout, not transaction completeness.", "Incorrect: sharding distributes data and does not make these writes atomic.", "Incorrect: eventual consistency alone does not guarantee all-or-nothing updates."], "Backend Developer"),
    ("Capgemini", "Full-Stack Developer", "Technical Interview", "Software Engineering", "CI/CD", "A deployment pipeline should stop before production when a critical test fails. Which pipeline behavior implements this safely?", ["Fail the pipeline stage and block promotion of that build", "Ignore the test result and deploy anyway", "Delete the test report after deployment", "Run tests only after all users receive the build"], "A", "A failing quality gate should prevent the artifact from being promoted to production.", ["Correct: blocking promotion prevents known failing builds from reaching production.", "Incorrect: ignoring a critical failure defeats the quality gate.", "Incorrect: deleting a report hides evidence but does not fix the defect.", "Incorrect: post-deployment testing exposes users before detecting the failure."], "Full-Stack Developer"),
    ("HCLTech", "Backend Developer", "Technical Interview", "Cloud Computing and DevOps", "Kubernetes Probes", "A Kubernetes container starts quickly, but its application needs 40 seconds to load a model before serving requests. Which probe avoids premature restarts during startup?", ["Configure a startup probe with a suitable failure window", "Set liveness to fail immediately during model loading", "Use readiness as a command to restart the process", "Remove all probes and assume every start succeeds"], "A", "A startup probe grants initialization time before liveness checks begin; readiness can then control when traffic is sent.", ["Correct: startup probes protect slow initialization from premature liveness failures.", "Incorrect: an immediate liveness failure can restart the app while it is healthy but initializing.", "Incorrect: readiness controls traffic eligibility; it is not a restart command.", "Incorrect: removing health checks can route traffic to an unready container."], "Backend Developer"),
    ("Tech Mahindra", "Graduate Engineer Trainee", "Technical Screening", "Computer Networks", "Subnetting", "A team needs 50 usable IPv4 host addresses in one subnet. Which smallest conventional subnet size provides enough usable hosts?", ["/26", "/27", "/28", "/29"], "A", "A /26 has 64 addresses and normally 62 usable host addresses, which covers 50; /27 has only 30 usable.", ["Correct: /26 supplies 62 usable addresses under conventional network/broadcast rules.", "Incorrect: /27 supplies only 30 usable addresses.", "Incorrect: /28 supplies only 14 usable addresses.", "Incorrect: /29 supplies only 6 usable addresses."], "Software Engineer"),
    ("Deloitte", "Data Analyst", "Technical Interview", "DBMS and SQL", "NULL Semantics", "A SQL query should include records where a nullable score is either missing or below 50. Which predicate expresses that condition?", ["score IS NULL OR score < 50", "score = NULL OR score < 50", "score <> NULL AND score < 50", "score BETWEEN NULL AND 50"], "A", "SQL NULL is tested with IS NULL; ordinary equality comparisons with NULL evaluate to UNKNOWN.", ["Correct: IS NULL tests absence, and OR includes low non-null scores.", "Incorrect: score = NULL does not test NULL in SQL's three-valued logic.", "Incorrect: <> NULL is also UNKNOWN, and AND would exclude missing values.", "Incorrect: BETWEEN with a NULL bound does not test for missing values."], "Data Analyst"),
    ("IBM", "Backend Developer", "Technical Interview", "Cloud Computing and DevOps", "Message Queues", "A consumer may crash after processing a message but before acknowledging it. What should a robust consumer do when that message is delivered again?", ["Make processing idempotent or deduplicate by message ID", "Assume delivery is exactly once without checking the broker", "Acknowledge before performing any work", "Discard every redelivered message"], "A", "At-least-once delivery can repeat a message, so idempotent effects or deduplication prevent duplicate business actions.", ["Correct: idempotence or deduplication handles legitimate redelivery.", "Incorrect: exactly-once behavior is not safe to assume across arbitrary side effects.", "Incorrect: acknowledging first can lose work if the consumer crashes before processing.", "Incorrect: redelivery may be the only copy that completes the work."], "Backend Developer"),
    ("LTIMindtree", "Data Analyst", "Technical Interview", "Data Structures and Algorithms", "Data Pipelines", "A daily ETL job should process only records added or changed since its last successful run. Which approach is most appropriate?", ["Persist a reliable watermark such as the last processed change timestamp", "Reload an arbitrary random subset each day", "Use the current wall-clock time without recording it", "Skip all records with null values"], "A", "A persisted watermark defines a reproducible incremental boundary; the job must handle late-arriving changes as part of its design.", ["Correct: a stored watermark supports repeatable incremental extraction.", "Incorrect: random subsets can omit or repeat records unpredictably.", "Incorrect: an unpersisted clock boundary can create gaps or duplicates after failure.", "Incorrect: null field values are not a valid general criterion for change detection."], "Data Analyst"),
    ("Amazon", "Backend Developer", "Technical Interview", "System Design", "Scalability", "A read-heavy product catalog experiences repeated identical lookups. Which design can reduce database load while keeping a bounded staleness window?", ["Use a cache with a defined TTL and invalidation strategy", "Send every read to a separate write transaction", "Disable database indexes", "Cache responses forever without invalidation"], "A", "A bounded TTL limits staleness, while invalidation handles known updates and reduces repeated reads.", ["Correct: TTL plus invalidation balances load reduction and freshness.", "Incorrect: write transactions add overhead and do not reduce read load.", "Incorrect: removing indexes usually makes database reads slower.", "Incorrect: permanent caching can serve stale catalog data indefinitely."], "Backend Developer"),
    ("Microsoft", "Frontend Developer", "Technical Interview", "Web Development", "Accessibility", "A web form shows an error only by turning a field border red. What change most improves accessibility?", ["Associate a textual error with the field and expose its invalid state", "Change the border to a darker red only", "Move the error text into an image with no alternative text", "Remove the field label"], "A", "Text and programmatic relationships communicate the error to screen readers and users who cannot distinguish color alone.", ["Correct: text plus programmatic association communicates both meaning and affected field.", "Incorrect: color-only feedback remains inaccessible to many users.", "Incorrect: an image without alternative text hides the error from assistive technology.", "Incorrect: removing the label makes the field harder to identify."], "Frontend Developer"),
    ("Google", "Software Engineer", "Technical Interview", "System Design", "Load Balancing", "A stateless web service runs on several instances behind a load balancer. One instance fails health checks. What should the load balancer do?", ["Stop routing new requests to the unhealthy instance", "Continue sending requests evenly to all instances", "Route only write requests to the failed instance", "Disable health checks"], "A", "Health-based routing removes an unhealthy target from service while healthy instances continue handling requests.", ["Correct: traffic should avoid an instance that fails health checks.", "Incorrect: equal routing ignores the known failure and increases errors.", "Incorrect: write requests are especially unsafe to send to an unhealthy target.", "Incorrect: disabling checks removes the mechanism that detects the failure."], "Software Engineer"),
    ("Oracle", "Backend Developer", "Technical Interview", "DBMS and SQL", "Isolation Levels", "Two concurrent transactions read the same inventory row; one updates it while the other relies on its earlier value. Which protection most directly prevents a lost update?", ["Use an appropriate locking or version-check strategy during the update", "Read the row once and never validate the update", "Disable transaction boundaries", "Store the quantity only in a client-side cache"], "A", "A lock or optimistic version check detects concurrent changes before committing a stale write.", ["Correct: locking or version checks prevent overwriting a concurrent update unnoticed.", "Incorrect: a stale read followed by an unconditional write can cause the lost update.", "Incorrect: removing transactions weakens coordination further.", "Incorrect: client-side state cannot coordinate concurrent server-side writers."], "Backend Developer"),
    ("Salesforce", "Full-Stack Developer", "Technical Interview", "Web Development", "Multi-Tenant SaaS", "A SaaS endpoint serves data for many customer organizations. What is the safest way to scope a query?", ["Derive the tenant from the authenticated identity and enforce it in the server-side query", "Accept any tenant_id supplied by the browser without checking it", "Filter tenants only in the UI after returning all rows", "Use a hidden form field as authorization"], "A", "Tenant identity must be trusted and enforced on the server so one customer cannot read another customer's rows.", ["Correct: authenticated tenant context plus server-side filtering enforces isolation.", "Incorrect: a client can tamper with the submitted tenant ID.", "Incorrect: returning other tenants' rows already exposes the data.", "Incorrect: hidden fields are still client-controlled and are not authorization."], "Backend Developer"),
    ("Walmart Global Tech", "Software Engineer", "Technical Interview", "System Design", "Inventory Consistency", "Two checkout requests compete for the last unit of an item. Which database operation prevents both from successfully reserving it?", ["An atomic conditional decrement that succeeds only when stock is positive", "Read stock in the client and decrement it later", "Allow negative inventory and repair it nightly", "Cache the stock value indefinitely"], "A", "A conditional atomic update serializes the stock check and decrement so only one reservation can consume the final unit.", ["Correct: the condition and decrement happen atomically in the database.", "Incorrect: separate client reads race and can both observe the same unit.", "Incorrect: accepting negative stock permits overselling before repair.", "Incorrect: stale cache values cannot safely arbitrate concurrent reservations."], "Backend Developer"),
    ("Flipkart", "Frontend Developer", "Technical Interview", "Web Development", "Client State", "A shopping-cart page optimistically updates its quantity before the server responds. The server rejects the update. What should the UI do?", ["Reconcile with the server response and restore or display the confirmed quantity", "Keep the optimistic value permanently", "Repeat the request without a limit", "Delete the entire cart"], "A", "Optimistic UI must reconcile failed mutations with authoritative server state and clearly show the failure.", ["Correct: server-confirmed state should replace the failed optimistic change.", "Incorrect: this leaves the UI inconsistent with persisted cart state.", "Incorrect: unlimited retries can overload the service and repeat failed actions.", "Incorrect: deleting unrelated cart items is not a valid recovery."], "Frontend Developer"),
    ("Zoho", "Full-Stack Developer", "Technical Interview", "Software Engineering", "API Pagination", "A CRM endpoint returns customer records in pages while new records may be inserted during browsing. Which pagination method is generally more stable for large changing datasets?", ["Keyset pagination using a stable ordered key", "Offset pagination with an ever-growing offset only", "Return every record in one response", "Sort by a non-unique random value"], "A", "Keyset pagination continues from the last seen ordered key and is less sensitive to inserts before the current offset.", ["Correct: stable keyset cursors avoid many offset-shift problems.", "Incorrect: inserts can shift offset pages and cause duplicates or skips.", "Incorrect: unbounded responses increase latency and memory use.", "Incorrect: a non-unique random order cannot provide stable continuation."], "Full-Stack Developer"),
    ("Freshworks", "Backend Developer", "Technical Interview", "Cybersecurity", "Rate Limiting", "A public support API is being abused by one client. Which control limits request volume without blocking every other customer?", ["Apply a per-client rate limit with a clear retry policy", "Disable the entire API for all customers", "Trust a client-supplied user name as the rate-limit identity", "Increase the server timeout indefinitely"], "A", "Per-client limits contain noisy consumers while a retry policy communicates when the client can try again.", ["Correct: scoped limits protect the service while preserving other customers' access.", "Incorrect: global shutdown affects legitimate users too.", "Incorrect: an untrusted client-supplied identity can be spoofed.", "Incorrect: longer timeouts do not control request rate and can worsen resource exhaustion."], "Backend Developer"),
]


def build() -> dict:
    questions = []
    for index, card in enumerate(CARDS, start=1):
        company, role, stage, category, topic, prompt, options, answer, explanation, option_explanations, role_name = card
        questions.append({
            "id": f"company-practice-{index:03d}", "prompt": prompt, "options": options,
            "correctAnswer": answer, "answer": options[ord(answer) - ord("A")], "explanation": explanation,
            "optionExplanations": option_explanations, "category": category, "topic": topic,
            "subTopic": topic, "difficulty": "Medium", "questionType": "MCQ",
            "tags": ["company-style", "practice", company.casefold()], "role": role_name,
            "associations": [{"company": company, "role": role_name, "recruitmentStage": stage,
                              "provenance": "Company-Style Practice Question",
                              "source": "AI-authored preparation scenario; not a verified historical company question"}],
            "provenance": "Company-Style Practice Question", "source": None,
            "verificationStatus": "Answer and distractors require independent review; not a historical question",
            "reviewStatus": "Pending Review", "structuralStatus": "Structurally Validated",
            "answerStatus": "Unverified", "sourceStatus": "No External Source",
            "expertReviewStatus": "Pending",
            "verificationEvidence": "Four distinct options and one designated answer; technical correctness remains pending independent review.",
        })
    return {"metadata": {"batch_id": "company-practice-001", "accepted_count": len(questions), "review_status": "Pending Review", "historical_questions": 0}, "questions": questions}


if __name__ == "__main__":
    bundle = build()
    OUTPUT.write_text(json.dumps(bundle, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(bundle["metadata"], ensure_ascii=False, indent=2))
